$H='<!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><script src="https://cdn.tailwindcss.com/3.4.17"></script><body class="bg-slate-100 p-4"><div class="max-w-5xl mx-auto">';
