$R=$_SESSION['role'];$ME=(int)$_SESSION['uid'];$SID=(int)$_SESSION['sid'];
function need(...$r){global $R;if(!in_array($R,$r))throw new Exception('ไม่มีสิทธิ์ทำรายการนี้');}
if($_SERVER['REQUEST_METHOD']=='POST'&&csrf_ok()){try{$a=$_POST['a']??'';
 if($a=='user'){need('admin');$un=trim($_POST['un']);$nm=trim($_POST['name']);if($un===''||$nm===''||strtolower($un)==='admin'||strlen($_POST['pw'])<8)throw new Exception('ชื่อผู้ใช้/ชื่อไม่ถูกต้อง หรือรหัสผ่านสั้นกว่า 8 ตัว');
  $db->beginTransaction();$sid=null;$role=$_POST['role']=='teacher'?'teacher':'student';
  if($role=='student'){if(!empty($_POST['esid']))$sid=(int)$_POST['esid'];else{$s=$db->prepare('INSERT INTO students(name) VALUES(?) RETURNING id');$s->execute([$nm]);$sid=$s->fetchColumn();$db->prepare('INSERT INTO credits(student_id,balance) VALUES(?,0)')->execute([$sid]);}}
  $db->prepare('INSERT INTO mc_users(username,pass_hash,role,name,student_id) VALUES(?,?,?,?,?)')->execute([$un,password_hash($_POST['pw'],PASSWORD_DEFAULT),$role,$nm,$sid]);$db->commit();}
 if($a=='pw'){need('admin');if(strlen($_POST['pw'])<8)throw new Exception('รหัสผ่านต้องยาวอย่างน้อย 8 ตัว');$db->prepare('UPDATE mc_users SET pass_hash=? WHERE id=?')->execute([password_hash($_POST['pw'],PASSWORD_DEFAULT),$_POST['id']]);}
 if($a=='topup'){need('admin');$db->prepare('UPDATE credits SET balance=balance+? WHERE student_id=?')->execute([(float)$_POST['n'],$_POST['sid']]);}
 if($a=='absence'){need('admin','student');$sid=$R=='student'?$SID:(int)($_POST['sid']??0);if(!$sid)throw new Exception('ยังไม่มีนักเรียน');$r=rule($_POST['course']);$ok=(strtotime($_POST['d'].' '.$_POST['tm'])-time())/3600>=$r['notice_hours'];
  $db->prepare('INSERT INTO absences(student_id,course,class_date,class_time,reason,eligible,note) VALUES(?,?,?,?,?,?,?)')->execute([$sid,$_POST['course'],$_POST['d'],$_POST['tm'],$_POST['reason'],$ok?'t':'f',$ok?'':'แจ้งล่วงหน้าไม่ถึง '.$r['notice_hours'].' ชม.']);}
 if($a=='book'){need('admin','student');$db->beginTransaction();$s=$db->prepare('SELECT * FROM absences WHERE id=? FOR UPDATE');$s->execute([$_POST['id']]);$ab=$s->fetch();
  if(!$ab||($R=='student'&&$ab['student_id']!=$SID))throw new Exception('ไม่พบใบลา');
  $t=$db->prepare("SELECT 1 FROM mc_users WHERE id=? AND role='teacher'");$t->execute([$_POST['tid']??0]);if(!$t->fetch())throw new Exception('กรุณาเลือกครู');
  [$ok,$m]=can_book($ab,$_POST['d'],$_POST['tm']);if(!$ok)throw new Exception($m);
  $db->prepare('INSERT INTO makeup_bookings(absence_id,student_id,teacher_id,slot_date,slot_time) VALUES(?,?,?,?,?)')->execute([$ab['id'],$ab['student_id'],$_POST['tid'],$_POST['d'],$_POST['tm']]);
  $db->prepare("UPDATE absences SET status='booked' WHERE id=?")->execute([$ab['id']]);$db->commit();}
 if(in_array($a,['attend','noshow','cancel'])){$a=='cancel'?need('admin','student'):need('admin','teacher');$db->beginTransaction();$s=$db->prepare("SELECT b.*,x.course FROM makeup_bookings b JOIN absences x ON x.id=b.absence_id WHERE b.id=? AND b.status='booked' FOR UPDATE");$s->execute([$_POST['id']]);$b=$s->fetch();if(!$b)throw new Exception('ไม่พบการจองที่รออยู่');
  if($R=='teacher'&&$b['teacher_id']!=$ME)throw new Exception('ไม่ใช่รอบของคุณ');if($R=='student'&&$b['student_id']!=$SID)throw new Exception('ไม่ใช่รอบของคุณ');
  if($a=='attend'){$c=rule($b['course'])['cost_credits'];$u=$db->prepare('UPDATE credits SET balance=balance-? WHERE student_id=? AND balance>=?');$u->execute([$c,$b['student_id'],$c]);if(!$u->rowCount())throw new Exception('เครดิตไม่พอหักสิทธิ์');
   $db->prepare("UPDATE makeup_bookings SET status='attended',credit_used=? WHERE id=?")->execute([$c,$b['id']]);$db->prepare("UPDATE absences SET status='done' WHERE id=?")->execute([$b['absence_id']]);}
  if($a=='noshow'){$db->prepare("UPDATE makeup_bookings SET status='no_show' WHERE id=?")->execute([$b['id']]);$db->prepare("UPDATE absences SET status='done' WHERE id=?")->execute([$b['absence_id']]);}
  if($a=='cancel'){$db->prepare("UPDATE makeup_bookings SET status='cancelled' WHERE id=?")->execute([$b['id']]);$db->prepare("UPDATE absences SET status='open' WHERE id=?")->execute([$b['absence_id']]);}
  $db->commit();}
 if($a=='rule'){need('admin');$db->prepare('INSERT INTO makeup_rules(course,notice_hours,max_per_month,window_days,cost_credits) VALUES(?,?,?,?,?) ON CONFLICT(course) DO UPDATE SET notice_hours=EXCLUDED.notice_hours,max_per_month=EXCLUDED.max_per_month,window_days=EXCLUDED.window_days,cost_credits=EXCLUDED.cost_credits')->execute([trim($_POST['course']),$_POST['nh'],$_POST['mm'],$_POST['wd'],$_POST['cc']]);}
 $_SESSION['m']='สำเร็จ';}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$_SESSION['m']='ผิดพลาด: '.$e->getMessage();}
